## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

// Testbench to hit R18 (R18_overrun_then_accept_newest) on uart_rx.
//
// Strategy:
//  1. Deliver a first word (8'hA5) while the AXI sink is stalled
//     (m_axis_tready low). The receiver raises m_axis_tvalid and holds it.
//  2. Deliver a second, newer word (8'hC3) while the first is still pending.
//     The receiver overruns: it presents 8'hC3 and pulses overrun_error for
//     one cycle while m_axis_tvalid is high and m_axis_tready is low. The
//     R18 cover-IP sets its "armed" flag on this tracked pulse.
//  3. Release back-pressure (m_axis_tready high). The next handshake carries
//     the newest word 8'hC3 with overrun_error low and no further overrun
//     pulse in between -> R18_overrun_then_accept_newest is covered.
//
// The DUT is the full `uart` (default parameters); R18 is bound to the
// internal uart_rx instance.

module tb;

  localparam int          CLK_PERIOD = 8;             // 125 MHz
  localparam logic [15:0] PRESCALE   = 16'd5;

  logic        clk             = 1'b0;
  logic        rst             = 1'b1;
  logic [7:0]  s_axis_tdata    = '0;
  logic        s_axis_tvalid   = 1'b0;
  logic [15:0] prescale        = PRESCALE;
  logic        m_axis_tready   = 1'b0;
  logic        rxd             = 1'b1;
  wire         s_axis_tready;
  wire         txd;
  wire         tx_busy;
  wire         rx_busy;
  wire [7:0]   m_axis_tdata;
  wire         m_axis_tvalid;
  wire         rx_overrun_error;
  wire         rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  // Full design under test, default parameters, driven only through ports.
  uart dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (m_axis_tready),
    .rxd               (rxd),
    .txd               (txd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1; wait_clks(2);
    rst = 1'b0; wait_clks(2);
  endtask

  // Drive one 8N1 byte on rxd (LSB first), each bit prescale*8 clocks wide.
  task automatic uart_send_byte(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    rxd = 1'b0; wait_clks(bit_clks);            // start bit
    for (int i = 0; i < 8; i++) begin
      rxd = b[i]; wait_clks(bit_clks);           // data bits
    end
    rxd = 1'b1; wait_clks(bit_clks);            // stop bit
  endtask

  initial begin
    do_reset();
    wait_clks(2);

    // --- Step 1: establish a pending, unread word under back-pressure ---
    uart_send_byte(8'hA5);
    wait (m_axis_tvalid === 1'b1);   // 8'hA5 delivered; held because tready low
    wait_clks(2);                    // short idle gap before the next frame

    // --- Step 2: a newer word 8'hC3 completes while 8'hA5 is still pending ---
    //             receiver overruns: m_axis_tdata becomes 8'hC3 and
    //             overrun_error pulses one cycle (tvalid high, tready low).
    uart_send_byte(8'hC3);
    wait (rx_overrun_error === 1'b1);  // tracked overrun pulse (word now 8'hC3)
    wait (rx_overrun_error === 1'b0);  // pulse over -> R18 cover-IP is armed
    @(negedge clk);                    // settle one half clock (tready still 0)

    // Sanity: the newest word is held pending, no active overrun.
    if (m_axis_tdata     !== 8'hC3) $fatal(1, "R18: m_axis_tdata=0x%02h (want C3)", m_axis_tdata);
    if (m_axis_tvalid    !== 1'b1)  $fatal(1, "R18: m_axis_tvalid not held");
    if (rx_overrun_error !== 1'b0)  $fatal(1, "R18: overrun_error still active");

    // --- Step 3: release back-pressure; the next handshake accepts 8'hC3 ---
    //             with overrun_error low and no further overrun in between.
    m_axis_tready = 1'b1;
    wait (m_axis_tvalid === 1'b0);   // handshake consumed the 8'hC3 word
    wait_clks(2);

    $display("PASS R18: overrun then accept newest 8'hC3");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule
